def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices.

    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    return sum(i for i in lst if i % 2 == 0 and lst.index(i) % 2 == 1)

def anti_shuffle(s):
    words = s.split()
    result = []
    for word in words:
        if word.isalpha():
            result.append(''.join(sorted(word)))
        else:
            result.append(word)
    return ' '.join(result)

